ALTER TABLE public.products ADD COLUMN reference_volume_ml numeric, ADD COLUMN reference_price numeric, ADD COLUMN pricing_step_percent numeric NOT NULL DEFAULT 10, ADD COLUMN auto_pricing boolean NOT NULL DEFAULT false;
ALTER TABLE public.products ADD CONSTRAINT pricing_reference_valid CHECK (pricing_step_percent >= 0 AND pricing_step_percent < 25 AND (reference_price IS NULL OR reference_price > 0) AND (reference_volume_ml IS NULL OR reference_volume_ml IN (100,300,500,1000,5000)));
ALTER TABLE public.product_variants ADD COLUMN retail_override boolean NOT NULL DEFAULT true;
ALTER TABLE public.site_settings ADD COLUMN payment_tax_percent numeric NOT NULL DEFAULT 6;
ALTER TABLE public.site_settings ADD CONSTRAINT tax_rate_valid CHECK (payment_tax_percent >= 0 AND payment_tax_percent < 100);
CREATE TABLE public.wholesale_levels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, discount_percent numeric NOT NULL CHECK(discount_percent >= 0 AND discount_percent <= 50), quantity_multiplier numeric, manual_only boolean NOT NULL DEFAULT false, sort integer NOT NULL DEFAULT 0, CHECK(quantity_multiplier IS NULL OR quantity_multiplier >= 1));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.wholesale_levels TO authenticated;
GRANT ALL ON public.wholesale_levels TO service_role;
ALTER TABLE public.wholesale_levels ENABLE ROW LEVEL SECURITY;
CREATE POLICY wholesale_levels_admin ON public.wholesale_levels FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.variant_wholesale (variant_id uuid PRIMARY KEY REFERENCES public.product_variants(id) ON DELETE CASCADE, base_price numeric, minimum_quantity integer NOT NULL DEFAULT 10 CHECK(minimum_quantity > 0), ozon_price numeric, max_discount_percent numeric CHECK(max_discount_percent >= 0 AND max_discount_percent <= 100), cost_price numeric CHECK(cost_price >= 0), minimum_margin_percent numeric NOT NULL DEFAULT 30 CHECK(minimum_margin_percent >= 0 AND minimum_margin_percent < 100), CHECK(base_price IS NULL OR base_price >= 0), CHECK(ozon_price IS NULL OR ozon_price >= 0));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.variant_wholesale TO authenticated;
GRANT ALL ON public.variant_wholesale TO service_role;
ALTER TABLE public.variant_wholesale ENABLE ROW LEVEL SECURITY;
CREATE POLICY variant_wholesale_admin ON public.variant_wholesale FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.dealer_accounts (user_id uuid PRIMARY KEY, lead_id uuid NOT NULL REFERENCES public.wholesale_leads(id), approved boolean NOT NULL DEFAULT false, manual_level_id uuid REFERENCES public.wholesale_levels(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.dealer_accounts TO authenticated;
GRANT ALL ON public.dealer_accounts TO service_role;
ALTER TABLE public.dealer_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY dealer_accounts_admin ON public.dealer_accounts FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY dealer_accounts_own ON public.dealer_accounts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.calculate_retail_price(_volume numeric,_reference_volume numeric,_reference_price numeric,_step numeric) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN array_position(ARRAY[100,300,500,1000,5000]::numeric[],_volume) IS NULL OR _reference_price IS NULL OR _reference_volume IS NULL THEN NULL ELSE round(_volume * _reference_price / _reference_volume * (1 + (array_position(ARRAY[100,300,500,1000,5000]::numeric[],_reference_volume)-array_position(ARRAY[100,300,500,1000,5000]::numeric[],_volume))*_step/100)) END $$;
CREATE OR REPLACE FUNCTION public.refresh_variant_retail() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.products; BEGIN SELECT * INTO p FROM public.products WHERE id=NEW.product_id; IF p.auto_pricing AND NOT NEW.retail_override THEN NEW.price := public.calculate_retail_price(NEW.volume_ml,p.reference_volume_ml,p.reference_price,p.pricing_step_percent); END IF; RETURN NEW; END $$;
CREATE TRIGGER variant_retail_price BEFORE INSERT OR UPDATE ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.refresh_variant_retail();
CREATE OR REPLACE FUNCTION public.refresh_product_retail() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.product_variants SET price=price WHERE product_id=NEW.id AND NOT retail_override; RETURN NEW; END $$;
CREATE TRIGGER product_retail_price AFTER UPDATE OF auto_pricing,reference_volume_ml,reference_price,pricing_step_percent ON public.products FOR EACH ROW EXECUTE FUNCTION public.refresh_product_retail();
CREATE OR REPLACE FUNCTION public.validate_wholesale_margin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tax numeric; BEGIN SELECT payment_tax_percent INTO tax FROM public.site_settings WHERE id=1; IF NEW.minimum_margin_percent + coalesce(tax,6) >= 100 THEN RAISE EXCEPTION 'Маржа и налог/комиссия должны в сумме быть меньше 100%%'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_wholesale_margin BEFORE INSERT OR UPDATE ON public.variant_wholesale FOR EACH ROW EXECUTE FUNCTION public.validate_wholesale_margin();
CREATE OR REPLACE FUNCTION public.dealer_quote(_variant_id uuid,_quantity integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE account public.dealer_accounts; w public.variant_wholesale; retail numeric; tax numeric; lvl public.wholesale_levels; chosen public.wholesale_levels; discount numeric:=0; result_price numeric; floor_price numeric; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Требуется вход'; END IF; SELECT * INTO account FROM public.dealer_accounts WHERE user_id=auth.uid() AND approved AND EXISTS(SELECT 1 FROM public.wholesale_leads WHERE id=lead_id AND status='approved'); IF NOT FOUND THEN RAISE EXCEPTION 'Оптовые цены доступны одобренным дилерам'; END IF; IF _quantity < 1 OR _quantity > 1000000 THEN RAISE EXCEPTION 'Некорректное количество'; END IF; SELECT v.price INTO retail FROM public.product_variants v JOIN public.products p ON p.id=v.product_id WHERE v.id=_variant_id AND p.status='published'; IF retail IS NULL THEN RETURN NULL; END IF; SELECT * INTO w FROM public.variant_wholesale WHERE variant_id=_variant_id; IF NOT FOUND THEN RETURN NULL; END IF; SELECT payment_tax_percent INTO tax FROM public.site_settings WHERE id=1; FOR lvl IN SELECT * FROM public.wholesale_levels LOOP IF ((NOT lvl.manual_only AND (lvl.quantity_multiplier IS NULL OR _quantity >= w.minimum_quantity*lvl.quantity_multiplier)) OR lvl.id=account.manual_level_id) AND lvl.discount_percent >= discount THEN discount:=lvl.discount_percent; chosen:=lvl; END IF; END LOOP; discount:=least(discount,coalesce(w.max_discount_percent,100)); result_price:=round(retail*(1-discount/100)); IF w.cost_price IS NOT NULL THEN IF 1-w.minimum_margin_percent/100-coalesce(tax,6)/100 <= 0 THEN RAISE EXCEPTION 'Некорректные настройки маржи'; END IF; floor_price:=ceil(w.cost_price/(1-w.minimum_margin_percent/100-coalesce(tax,6)/100)); result_price:=greatest(result_price,floor_price); END IF; RETURN jsonb_build_object('variant_id',_variant_id,'retail_price',retail,'price',result_price,'quantity',_quantity,'minimum_quantity',w.minimum_quantity,'level',chosen.name); END $$;
REVOKE ALL ON FUNCTION public.dealer_quote(uuid,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.dealer_quote(uuid,integer) TO authenticated;
UPDATE public.products SET auto_pricing=true,reference_volume_ml=CASE WHEN slug='ochistitel-clean-black' THEN 100 ELSE 500 END,reference_price=CASE slug WHEN 'antiprokol' THEN 2000 WHEN 'antiprokol-lite-dlya-shvov' THEN 1300 ELSE 300 END,pricing_step_percent=CASE WHEN slug='ochistitel-clean-black' THEN 5 ELSE 10 END WHERE slug IN ('antiprokol','antiprokol-lite-dlya-shvov','ochistitel-clean-black');
UPDATE public.product_variants v SET retail_override=false FROM public.products p WHERE p.id=v.product_id AND p.auto_pricing;
INSERT INTO public.variant_wholesale(variant_id,minimum_quantity,max_discount_percent) SELECT v.id,CASE WHEN p.slug='antiprokol' THEN CASE v.volume_ml WHEN 300 THEN 100 WHEN 500 THEN 100 WHEN 1000 THEN 50 ELSE 10 END WHEN p.slug='antiprokol-lite-dlya-shvov' THEN CASE v.volume_ml WHEN 1000 THEN 30 WHEN 5000 THEN 10 ELSE 50 END WHEN p.slug='ochistitel-clean-black' THEN CASE v.volume_ml WHEN 1000 THEN 10 WHEN 5000 THEN 5 ELSE 100 END WHEN p.slug LIKE 'zhidkaya-zaplatka-%' OR p.slug='armirovannyj-gel' THEN 100 ELSE 10 END,CASE WHEN p.slug='otverditel-antiprokola' THEN 35 ELSE NULL END FROM public.product_variants v JOIN public.products p ON p.id=v.product_id;